  static void ComponentClassification(){
   string root=Path.Combine(LauncherTestPaths.Root,"catalog-classification-"+Guid.NewGuid().ToString("N"));var e=new Engine(Path.Combine(root,"Game"),Path.Combine(root,"User"),Path.Combine(root,"Data"),true);Put(Path.Combine(e.Game,"game-version.txt"),"42.12.3");
   string[] ids={"Ordinary","Viewpoint","ZombieBuddy",ShootClient.Id,ChinesePatch.Id,PresentationBridge.Id,ViewpointAddons.All[0].Id,"\\Viewpoint","\\"+ViewpointAddons.All[0].Id,"Opaque\\Viewpoint"};
   for(int i=0;i<ids.Length;i++)Put(Path.Combine(e.User,"mods","item-"+i,"42/mod.info"),"id="+ids[i]+"\nname=Same misleading author title\n");
   var before=Directory.GetFiles(root,"*",SearchOption.AllDirectories).ToDictionary(p=>p,p=>File.ReadAllBytes(p));var rows=Rows(D(Call("Catalog",e)),"mods").Select(D).ToArray();
   Check(rows.All(r=>r.ContainsKey("componentManaged")&&r["componentManaged"] is bool),"catalog explicitly classifies every ID for component-only bulk handling");
   foreach(string id in ids){bool expected=id!="Ordinary"&&id!="Opaque\\Viewpoint";Check((bool)rows.Single(r=>(string)r["id"]==id)["componentManaged"]==expected,"managed component classification without name/source inference: "+id);}
   Check(before.All(p=>File.ReadAllBytes(p.Key).SequenceEqual(p.Value))&&Directory.GetFiles(root,"*",SearchOption.AllDirectories).Length==before.Count,"classification changes no fixture file or creates launcher data");
  }
  static void ConcurrentWriters(Engine e,string root,string original){string file=Path.Combine(e.User,"Saves/Survivor/Concurrent/mods.txt");Put(file,original);string stamp=(string)D(Call("Read",e,"Survivor/Concurrent"))["stamp"];string name;using(var hash=SHA256.Create())name="Local\\OrangeSaveProfiles-"+BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(Path.GetFullPath(file).ToUpperInvariant()))).Replace("-","").ToLowerInvariant();int successes=0,stale=0;Exception unexpected=null;var began=new CountdownEvent(2);var done=new CountdownEvent(2);ThreadStart writer=()=>{began.Signal();try{var other=new Engine(e.Game,e.User,Path.Combine(root,"Data"),true);Call("Save",other,"Survivor/Concurrent",stamp,new[]{"A"},true);Interlocked.Increment(ref successes);}catch(Exception x){if(x.Message.Contains("修改"))Interlocked.Increment(ref stale);else unexpected=x;}finally{done.Signal();}};using(var mutex=new Mutex(false,name)){mutex.WaitOne();var first=new Thread(writer);var second=new Thread(writer);first.Start();second.Start();began.Wait();bool prematurelyFinished=done.Wait(800);bool unchanged=Encoding.UTF8.GetString(File.ReadAllBytes(file))==original;mutex.ReleaseMutex();first.Join();second.Join();Check(!prematurelyFinished&&unchanged,"save writers wait for per-save cross-instance mutex before snapshot/write");}if(unexpected!=null)throw unexpected;Check(successes==1&&stale==1,"same-stamp concurrent instances yield one success and one stale refusal");Check(File.ReadAllText(file).Contains("    mod = A,")&&!File.ReadAllText(file).Contains("    mod = B,"),"winning concurrent write persists complete output");}
